_GITIGNORE = """\
.godot/
*.translation
export.cfg
"""


def godot_scaffold_files(name: str, slug: str, description: str = "") -> dict[str, str]:
    from .game_factory import wants_godot_3d_slice

    if wants_godot_3d_slice(name, description):
        from .playground_godot3d_scaffold import godot3d_scaffold_files
        return godot3d_scaffold_files(name, slug, description)
    title = (name or slug or "GodotGame").strip()
    desc = (description or title).strip()[:400]
    mapping = {"__NAME__": title, "__SLUG__": slug or "godot-game", "__DESC__": desc}
    raw = {
        "project.godot": _PROJECT_GODOT,
        "scenes/main.tscn": _MAIN_TSCN,
        "scripts/player.gd": _PLAYER_GD,
        "scripts/hud.gd": _HUD_GD,
        "scripts/autoload/game.gd": _GAME_GD,
        "icon.svg": _ICON_SVG,
        "studio/preview/index.html": _PREVIEW_HTML,
        "README.md": _README,
        ".gitignore": _GITIGNORE,
    }
    out: dict[str, str] = {}
    for rel, content in raw.items():
        text = content
        for k, v in mapping.items():
            text = text.replace(k, v)
        out[rel] = text
    return out


def write_godot_scaffold(pdir: Path, name: str, slug: str, description: str = "") -> list[str]:
    from .game_factory import wants_godot_3d_slice

    if wants_godot_3d_slice(name, description):
        from .playground_godot3d_scaffold import write_godot3d_scaffold
        return write_godot3d_scaffold(pdir, name, slug, description)
    pdir = Path(pdir)
    pdir.mkdir(parents=True, exist_ok=True)
    written: list[str] = []
    for rel, content in godot_scaffold_files(name, slug, description).items():
        target = pdir / rel
        if target.exists():
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        written.append(rel)
    from .godot_bridge import BRIDGE_REL, ensure_bridge, ensure_import_sidecars

    ensure_bridge(pdir)
    if BRIDGE_REL not in written:
        written.append(BRIDGE_REL)
    ensure_import_sidecars(pdir)
    try:
        from .godot_first import ensure_contract
        ensure_contract(pdir, slug=slug, name=name)
        for rel in ("studio/godot_contract.json", "studio/release_manifest.json", "export_presets.cfg"):
            if rel not in written and (pdir / rel).is_file():
                written.append(rel)
    except Exception:
        log.debug("godot contract skipped", extra={"slug": slug})
    if written:
        log.info("godot scaffold: %s → %s", slug, written)
    return written


def verify_godot_scaffold(slug: str, paths: list[str] | None = None) -> dict:
    from . import playground as pg

    root = pg.project_dir(slug)
    if paths is None:
        paths = [t["path"] for t in pg.read_tree(slug)]
    issues: list[str] = []
    if "project.godot" not in paths:
        issues.append("липсва project.godot")
    gd = [p for p in paths if p.endswith(".gd")]
    tscn = [p for p in paths if p.endswith(".tscn")]
    if not gd:
        issues.append("няма GDScript (.gd)")
    if not tscn:
        issues.append("няма сцена (.tscn)")
    preview = (root / "studio" / "preview" / "index.html").is_file()
    if not preview and "studio/preview/index.html" not in paths:
        issues.append("липсва studio/preview/index.html")
    dod = None
    if (root / "scenes" / "main.tscn").is_file():
        from .godot_dod import dod_v2_static
        dod = dod_v2_static(root)
        if not dod.get("ok"):
            issues.extend(str(x) for x in (dod.get("blocking") or ["dod_v2"]))
    return {
        "ok": not issues,
        "issues": issues,
        "error": "; ".join(issues),
        "gd_count": len(gd),
        "tscn_count": len(tscn),
        "file_count": len(paths),
        "dod": dod or {},
    }
